const Stat = (ui: RichUi, key: string, label: string, value: string, color?: string) => {
  const { Box, Text } = ui

  return (
    <Box key={key} flexDirection="column" minWidth={12}>
      <Text dimColor>{label}</Text>
      <Text bold color={color}>
